import {readFileSync} from 'node:fs';
import {randomUUID as uuid} from 'node:crypto';
import assert from 'node:assert/strict';
const {PGlite}=await import(process.env.PGLITE_MODULE ?? '@electric-sql/pglite');
const db=new PGlite();
const q=async(sql,args=[]) => (await db.query(sql,args)).rows;
const company=uuid(),actor=uuid(),auth=uuid(),branch=uuid(),supplier=uuid(),po=uuid(),line=uuid(),item=uuid();
let checks=0;
try {
await db.exec(`create schema auth;
create function auth.uid() returns uuid language sql as 'select current_setting(''test.auth'')::uuid';
create function public.has_permission(text) returns boolean language sql as 'select current_setting(''test.allowed'')::boolean';
create function public.can_access_inventory_branch(uuid,uuid) returns boolean language sql as 'select $2=current_setting(''test.branch'')::uuid';
create table staffs(id uuid,auth_user_id uuid,company_id uuid,status text,deleted_at timestamptz);
create table purchase_orders(id uuid,company_id uuid,supplier_id uuid,branch_id uuid,status text,deleted_at timestamptz);
create table purchase_order_lines(id uuid,purchase_order_id uuid,item_id uuid,qty_ordered numeric,qty_received numeric,qty_cancelled numeric);
create table documents(id uuid primary key,company_id uuid,document_no text,document_type text,title text,status text,approval_status text,current_step text,related_entity_type text,related_entity_id uuid,created_by uuid,updated_by uuid);
create table goods_receivings(id uuid primary key,company_id uuid,document_id uuid,purchase_order_id uuid,grn_no text,supplier_id uuid,received_date date,branch_id uuid,status text,received_by uuid,remarks text,created_by uuid,updated_by uuid,idempotency_key uuid,deleted_at timestamptz);
create table goods_receiving_lines(goods_receiving_id uuid,purchase_order_line_id uuid,item_id uuid,ordered_qty numeric,previously_received_qty numeric,pending_qty numeric,received_qty numeric,rejected_qty numeric,uom text,unit_cost numeric,batch_no text,expiry_date date,remarks text,received_base_qty numeric,rejected_base_qty numeric,conversion_to_base_uom_snapshot numeric,conversion_source text,conversion_confirmed_by uuid,conversion_confirmed_at timestamptz,remember_conversion boolean,over_receipt_reason text);
create table document_revisions(document_id uuid,revision_no int,change_summary text,changed_by uuid);`);
await q("select set_config('test.auth',$1,false),set_config('test.allowed','true',false),set_config('test.branch',$2,false)",[auth,branch]);
await q("insert into staffs values($1,$2,$3,'active',null)",[actor,auth,company]);
await q("insert into purchase_orders values($1,$2,$3,$4,'sent',null)",[po,company,supplier,branch]);
await q("insert into purchase_order_lines values($1,$2,$3,10,0,0)",[line,po,item]);
const payload=()=>({grn_no:'TEST',branch_id:branch,supplier_id:supplier,purchase_order_id:po,idempotency_key:uuid(),lines:[{purchase_order_line_id:line,item_id:item,ordered_qty:10,previously_received_qty:0,pending_qty:10,received_qty:2,rejected_qty:0,uom:'PCS',unit_cost:1,received_base_qty:2,rejected_base_qty:0,conversion_to_base_uom_snapshot:1}]});
const rpc=p=>q('select create_goods_receiving_atomic($1::jsonb) result',[JSON.stringify(p)]);
const rejects=async(p,re)=>{await assert.rejects(()=>rpc(p),re);checks++;};
const original=readFileSync('supabase/migrations/240_editable_goods_receiving_and_controlled_over_receipt.sql','utf8');
await db.exec(original.slice(original.indexOf('create or replace function public.create_goods_receiving_atomic'),original.indexOf('create or replace function public.update_goods_receiving_draft_atomic')));
await rejects(payload(),/purchase_order_id.*ambiguous/);
await db.exec(readFileSync('supabase/migrations/328_goods_receiving_column_disambiguation.sql','utf8'));
const p=payload(), result=(await rpc(p))[0].result;
assert.equal(result.idempotent,false);checks++;
assert.equal((await rpc(p))[0].result.id,result.id);checks++;
assert.equal((await q('select count(*)::int n from goods_receivings'))[0].n,1);checks++;
assert.equal((await q('select received_qty from goods_receiving_lines'))[0].received_qty,'2');checks++;
await q("select set_config('test.allowed','false',false)");await rejects(payload(),/Missing permission/);
await q("select set_config('test.allowed','true',false)");
await rejects({...payload(),purchase_order_id:uuid()},/unavailable for receiving/);
await q('update purchase_orders set company_id=$1',[uuid()]);await rejects(payload(),/unavailable for receiving/);await q('update purchase_orders set company_id=$1',[company]);
const wrongLine=payload();wrongLine.lines[0].purchase_order_line_id=uuid();await rejects(wrongLine,/does not belong/);
const negative=payload();negative.lines[0].received_qty=-1;await rejects(negative,/cannot be negative/);
const excess=payload();excess.lines[0].received_qty=11;await rejects(excess,/Explain why/);
excess.lines[0].over_receipt_reason='Supplier extra';assert.equal((await rpc(excess))[0].result.idempotent,false);checks++;
const missingConversion=payload();missingConversion.lines[0].conversion_to_base_uom_snapshot=0;await rejects(missingConversion,/Confirm.*conversion/);
const invalid=payload();invalid.lines[0].unit_cost='invalid';const before=(await q('select count(*)::int n from documents'))[0].n;await rejects(invalid,/invalid input syntax/);assert.equal((await q('select count(*)::int n from documents'))[0].n,before);checks++;
console.log(`${checks} PostgreSQL execution checks passed, including reproduction, creation, idempotency, permission/tenant rejection, quantity rules and rollback.`);
} finally {await db.close();}
